#!/bin/bash
# ===========================================================================
# DEPLOY_v2_fix — طبقة الاسترجاع v2 بعد الإصلاح + بوابة الانحدار الكاملة
#
# لا تفعيل إنتاج: علم LEGALMIND_RETRIEVAL_V2 لا يُضبط هنا. لا مساس بـapp.py.
# يُحدَّث mcp/server.py (إصلاح JUR-* والجرد) مع نسخة احتياطية تلقائية.
#
# الاستعمال: احفظه ملفًا ثم:  bash DEPLOY_v2_fix.sh
#            أو الصقه كاملًا — الجزء الأخير يعمل مباشرةً بلا حيلة $0.
# ===========================================================================
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/v2fix.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/v2fix.b64 > /tmp/v2fix.tgz || { echo "B64_FAIL"; exit 1; }
[ -f mcp/server.py ] && cp mcp/server.py "mcp/server.py.bak_$(date +%s)"
tar xzf /tmp/v2fix.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
echo "الملفات وُضعت (retrieval/ + mcp/server.py + بوابة القياس). app.py لم يُمَس."
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/retrieval_layer_validate.py > /tmp/v2val.log 2>&1 &
disown
echo "بدأت بوابة الانحدار (PID $!). تابع:  tail -f /tmp/v2val.log"
